/* Spread the correct answer around so it isn't always "A" */
function spreadAnswers(list){let n=0;list.forEach(set=>set.qs.forEach(q=>{if(q.type==='tf'||q.type==='type')return;const k=(n*5+1+(n>>2))%q.a.length;n++;const right=q.a[q.c];const rest=q.a.filter((_,i)=>i!==q.c);rest.splice(k,0,right);q.a=rest;q.c=k}));return list}


